mapper.update:
UPDATE xsy_payment_refund
SET recovery_lease_until = NULL, recovery_status = #{result}, recovery_message = #{detail},
    next_recovery_at = CURRENT_TIMESTAMP + (#{delaySeconds} * INTERVAL '1 second')
WHERE id = #{id}
    AND deleted = FALSE
    AND recovery_attempts = #{attempt}

UPDATE xsy_payment_refund
SET provider_refund_no = #{providerRefundNo}, updated_by = #{operator}
WHERE id = #{id}
    AND deleted = FALSE
    AND (provider_refund_no IS NULL OR provider_refund_no = #{providerRefundNo})

mapper.select:
SELECT r.*
FROM xsy_payment_refund r
JOIN xsy_payment_intent i ON i.id = r.intent_id
    AND i.deleted = FALSE
WHERE r.deleted = FALSE

AND r.transaction_id = #{query.transactionId}
AND r.intent_id = #{query.intentId}
AND r.provider = #{query.provider}
AND r.status = #{query.status}
AND r.source_type = #{query.sourceType}
AND r.source_id = #{query.sourceId}

    AND (r.refund_no ILIKE CONCAT('%', #{query.keyword}, '%') OR
        r.provider_refund_no ILIKE CONCAT('%', #{query.keyword}, '%'))

ORDER BY r.created_at DESC, r.id DESC

SELECT *
FROM xsy_payment_refund
WHERE provider = #{provider}
    AND provider_refund_no = #{providerRefundNo}
    AND deleted = FALSE

mapper.update:
UPDATE xsy_payment_refund
SET status = 'FAILED', failure_code = #{failureCode}, failure_message = #{failureMessage},
    version = version + 1, updated_at = CURRENT_TIMESTAMP, updated_by = #{operator}
WHERE id = #{id}
    AND status IN ('CREATED', 'PROCESSING')
    AND deleted = FALSE

UPDATE xsy_payment_refund
SET status = 'PROCESSING', provider_refund_no = #{providerRefundNo}, version = version + 1,
    updated_at = CURRENT_TIMESTAMP, updated_by = #{operator}
WHERE id = #{id}
    AND status = 'CREATED'
    AND deleted = FALSE
